  function automatic logic lookup(input logic [63:0] truth_value,input logic [5:0] variables);
    logic [63:0] reduced;
    integer position;
    begin
      reduced=truth_value;
      for(position=5;position>=0;position=position-1)
        if(position==5) reduced={32'b0,variables[position] ? reduced[63:32] : reduced[31:0]};
        else if(position==4) reduced={48'b0,variables[position] ? reduced[31:16] : reduced[15:0]};
